-- MP-0010: guarded editorial content import. Deploy portraits before applying.

begin;

do $$ begin
 if not exists(select 1 from public.entities where slug='government' and type='bloc') then raise exception 'MP-0010: missing or wrong parent'; end if;
 if not exists(select 1 from public.entities where slug='pas' and type='party') then raise exception 'MP-0010: missing or wrong parent'; end if;
 if not exists(select 1 from public.entities where slug='wawasan' and type='party') then raise exception 'MP-0010: missing or wrong parent'; end if;
 if exists(select 1 from public.entities where slug in ('nik-muhammad-zawawi-salleh','wan-ahmad-fayhsal','zahari-kechik') and (type <> 'politician' or owner_id is not null)) then raise exception 'MP-0010: ownership or type conflict'; end if;
 if exists(select 1 from public.entities where type='politician' and lower(constituency) in ('pasir puteh','machang','jeli') and slug not in ('nik-muhammad-zawawi-salleh','wan-ahmad-fayhsal','zahari-kechik')) then raise exception 'MP-0010: constituency identity conflict'; end if;
 if exists(select 1 from public.milestones m join public.entities e on e.id=m.entity_id where m.import_key like 'MP-0010:%' and (m.source_type <> 'editorial' or e.slug not in ('nik-muhammad-zawawi-salleh','wan-ahmad-fayhsal','zahari-kechik') or m.import_key not like 'MP-0010:' || e.slug || ':%')) then raise exception 'MP-0010: milestone identity conflict'; end if;
end $$;

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'nik-muhammad-zawawi-salleh','Nik Muhammad Zawawi Salleh','opposition','Member of the Dewan Rakyat','Pasir Puteh','Kelantan','Nik Muhammad Zawawi Salleh represents Pasir Puteh, Kelantan, in the Dewan Rakyat. A PAS member.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4067','/portraits/nik-muhammad-zawawi-salleh.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P028.jpg','Parliament of Malaysia','2026-11-09','[{"label": "Parliament · official profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4067"}, {"label": "PAS · current parliamentary representatives", "url": "https://pas.org.my/ahli-parlimen-pas-pru-ke-15/"}]'::jsonb from public.entities parent where parent.slug='pas' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'wan-ahmad-fayhsal','Wan Ahmad Fayhsal Wan Ahmad Kamal','opposition','Member of the Dewan Rakyat','Machang','Kelantan','Wan Ahmad Fayhsal Wan Ahmad Kamal represents Machang, Kelantan, in the Dewan Rakyat. A Parti Wawasan Negara member.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4068','/portraits/wan-ahmad-fayhsal.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P029.jpg','Parliament of Malaysia','2026-11-09','[{"label": "Parliament · official profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4068"}, {"label": "Wawasan · announced leadership, 21 Jun 2026", "url": "https://www.thestar.com.my/news/nation/2026/06/21/parti-wawasan-negara-unveils-central-leadership-line-up"}]'::jsonb from public.entities parent where parent.slug='wawasan' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'zahari-kechik','Zahari Kechik','government','Member of the Dewan Rakyat','Jeli','Kelantan','Zahari Kechik represents Jeli, Kelantan, in the Dewan Rakyat. An independent MP supporting the government under a confidence-and-supply agreement.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4069','/portraits/zahari-kechik.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P030.jpg','Parliament of Malaysia','2026-11-09','[{"label": "Parliament · official profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4069"}, {"label": "Independent MP · 29 Oct 2026 confidence-and-supply agreement", "url": "https://bernama.com/bm/am/news.php?id=2627381"}]'::jsonb from public.entities parent where parent.slug='government' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

do $$ begin if (select count(*) from public.entities where slug in ('nik-muhammad-zawawi-salleh','wan-ahmad-fayhsal','zahari-kechik') and type='politician' and owner_id is null) <> 3 then raise exception 'MP-0010: concurrent ownership or identity change'; end if; end $$;

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'MP-0010:zahari-kechik:budget-2027-csa','Support Budget 2027 under the CSA','Governance',null,null,null,'2026-10-29','https://bernama.com/bm/am/news.php?id=2627381',null,null,'The MP was a named agreement signatory.','Signing is documented; subsequent budget votes were not verified. Outcome and completion remain unknown.','2026-11-09','editorial',false from public.entities e where e.slug='zahari-kechik' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

